from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _round(numerator, mode):
    if mode == "half_up":
        return (numerator + 5000) // 10000
    return numerator // 10000


def _ledger(data, revision_first, tax_discounted, refunds):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if revision_first:
            key = (event.get("revision", 0), pos)
        else:
            key = (sequence, event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if tax_discounted else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if refunds and event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    from itertools import product

    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    options = [[None] + list(packages[name]) for name in names]
    best_vector = None
    best_versions = None

    for rows in product(*options):
        versions = {name: row["version"]
                    for name, row in zip(names, rows) if row is not None}
        if any(name not in versions or
               not bounds[0] <= versions[name] <= bounds[1]
               for name, bounds in data["roots"].items()):
            continue
        if any(name in versions and versions[name] in blocked.get(name, [])
               for name in names):
            continue
        if any(name in versions and versions[name] != version
               for name, version in pins.items()):
            continue

        graph = {name: [] for name in versions}
        valid = True
        for name, row in zip(names, rows):
            if row is None:
                continue
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if (target not in versions or
                        not dep["min"] <= versions[target] <= dep["max"]):
                    valid = False
                    break
                graph[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        pending = list(data["roots"])
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            pending.extend(graph[name])
        if reachable != set(versions):
            continue

        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(child) for child in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in graph):
            continue

        vector = tuple(versions.get(name, -1) for name in names)
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best_versions = versions

    if best_vector is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _quota_intervals(data):
    from itertools import combinations

    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for chosen in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in chosen))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(chosen, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _temporal_routes(data):
    import heapq

    required_bits = {node: 1 << i
                     for i, node in enumerate(data.get("required", []))}
    full_mask = (1 << len(required_bits)) - 1
    source = data["source"]
    target = data["target"]
    initial = (source, required_bits.get(source, 0), data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"],) + initial]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == target and mask == full_mask and remaining == 0:
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, remaining - 1))
            for duration, next_remaining in choices:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | required_bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time,) + next_state)

    return {"arrival": None}


SOLVERS = {
    "component_01": lambda d: _ledger(d, False, False, True),
    "component_02": lambda d: _ledger(d, True, True, True),
    "component_03": lambda d: _ledger(d, False, True, True),
    "component_04": lambda d: _ledger(d, True, False, True),
    "component_05": lambda d: _ledger(d, False, False, True),
    "component_06": _dependencies,
    "component_07": _quota_intervals,
    "component_08": _temporal_routes,
}
